# 🚀 RUN THIS CELL IN KAGGLE TO APPLY FIX & RESTART LIVE SERVER (ZERO REINSTALL NEEDED)
import os, sys, time, gzip, base64, subprocess, types

print("🛑 Stopping old server...")
os.system("pkill -9 -f 'main.py' 2>/dev/null")
os.system("pkill -9 -f 'uvicorn' 2>/dev/null")
time.sleep(1)

# Kaggle environment fix: remove incompatible torchvision binary to prevent 'torchvision::nms' crash on pipeline import
os.system("pip uninstall -y torchvision 2>/dev/null || true")

# Ensure f5-tts, edge-tts, and gtts are installed
for pkg in ["f5-tts", "edge-tts", "gtts"]:
    try:
        __import__(pkg.replace("-", "_"))
    except ImportError:
        print(f"📦 Installing {pkg} package...")
        os.system(f"pip install -q {pkg}")

dest_dir = "/kaggle/working/vocaly"
backend_dir = os.path.join(dest_dir, "backend")
os.makedirs(backend_dir, exist_ok=True)

mods = [
    ("main.py", ""),
    ("tts_engine.py", ""),
    ("alerts_service.py", ""),
    ("config.py", ""),
    ("models.py", ""),
    ("twilio_service.py", ""),
    ("llm_engine.py", ""),
    ("telegram_alert.py", ""),
    ("database.py", ""),
    ("rag_engine.py", ""),
]

for fname, b64_str in mods:
    data = gzip.decompress(base64.b64decode(b64_str))
    for d in [dest_dir, backend_dir, "/kaggle/working", "/kaggle/working/backend"]:
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, fname), "wb") as f:
            f.write(data)

# Sync backend/__init__.py singleton guard
_init_data = gzip.decompress(base64.b64decode(""))
for _bd in [backend_dir, "/kaggle/working/backend"]:
    os.makedirs(_bd, exist_ok=True)
    with open(os.path.join(_bd, "__init__.py"), "wb") as _f:
        _f.write(_init_data)

# Ensure voice_clone.mp3 and default_voices directory are synced
import shutil, glob
vclones = [p for p in glob.glob("/kaggle/**/voice_clone.mp3", recursive=True) if os.path.getsize(p) > 0]
if vclones:
    for target in ["/kaggle/working/vocaly/voice_clone.mp3", "/kaggle/working/vocaly/backend/voice_clone.mp3", "/kaggle/working/voice_clone.mp3"]:
        if os.path.abspath(vclones[0]) != os.path.abspath(target):
            try:
                shutil.copy2(vclones[0], target)
            except Exception:
                pass

for src in ["/kaggle/working/vocaly/default_voices", "/kaggle/working/vocaly/backend/default_voices", "/kaggle/working/backend/default_voices", "/kaggle/working/default_voices"] + glob.glob("/kaggle/input/**/default_voices", recursive=True):
    if os.path.isdir(src) and os.listdir(src):
        for target in ["/kaggle/working/vocaly/default_voices", "/kaggle/working/vocaly/backend/default_voices"]:
            if os.path.abspath(src) != os.path.abspath(target):
                try:
                    shutil.copytree(src, target, dirs_exist_ok=True)
                except Exception:
                    pass
        break

# Compatibility shield for Kaggle environment against torchvision::nms mismatch
try:
    import transformers.utils.import_utils as _t_iu
    _t_iu.is_torchvision_available = lambda: False
    if 'torchvision' not in sys.modules:
        _tv_dummy = types.ModuleType('torchvision')
        _tv_dummy.__spec__ = types.ModuleType.__spec__
        _tv_transforms = types.ModuleType('torchvision.transforms')
        _tv_f = types.ModuleType('torchvision.transforms.functional')
        _tv_transforms.InterpolationMode = type('InterpolationMode', (), {'NEAREST': 'nearest', 'BILINEAR': 'bilinear'})
        _tv_dummy.transforms = _tv_transforms
        sys.modules['torchvision'] = _tv_dummy
        sys.modules['torchvision.transforms'] = _tv_transforms
        sys.modules['torchvision.transforms.functional'] = _tv_f
except Exception:
    pass

print("✅ Applied: F5-TTS & LuxTTS voice cloning with clean reference audio resolution!")
print("✅ Applied: Chatterbox removed cleanly; Kannada/Hindi/English voices synced!")
print("✅ Applied: Voice Dropdown deduplication & Language-specific filtering (Kannada/Hindi/English)!")
print("✅ Applied: Indic voice edge-tts / gTTS fallbacks & pre-warming greeting dynamic synthesis!")
print("✅ Applied: Fixed Twilio WhatsApp sender and phone regex parsing (import re)!")
print("✅ Applied: Contact card and Listen button UI spacing perfected!")
print("✅ Applied: Voice isolation (Alex vs custom voices), dynamic persona/greeting sync & Mandatory Re-Warm!")

# Restart live server in background
time.sleep(1)
print("🚀 Launching updated Vocalyx live server...")
os.environ["PYTHONPATH"] = f"/kaggle/working:/kaggle/working/vocaly:/kaggle/working/vocaly/backend:{os.environ.get('PYTHONPATH', '')}"

proc = subprocess.Popen(
    ["python", "-u", "main.py"],
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
    text=True,
    bufsize=1,
    cwd="/kaggle/working/vocaly",
    env=dict(os.environ, PYTHONPATH="/kaggle/working:/kaggle/working/vocaly:/kaggle/working/vocaly/backend")
)
time.sleep(2)
print("🎉 Vocalyx server restarted successfully! Monitoring logs:")
try:
    for line in iter(proc.stdout.readline, ""):
        print(line, end="", flush=True)
except KeyboardInterrupt:
    proc.terminate()
